INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-3',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Slow Spread of Paper Money","passageText":"Paper currency did not arrive as a sudden invention. In medieval China, merchants began issuing receipts for metal coins they had deposited with trusted warehouses. Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks. The state eventually recognised the convenience and issued its own notes, but early experiments collapsed when rulers printed more paper than they could redeem in metal. Europe adopted similar instruments centuries later through bills of exchange used by traders. The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","gapSentence":{"before":"Paper currency did not arrive as a sudden invention. In medieval China, merchants began issuing receipts for metal coins they had deposited with trusted warehouses. Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks. The state eventually recognised the convenience and issued its own notes, but early experiments collapsed when rulers printed more paper than they could ","after":" in metal. Europe adopted similar instruments centuries later through bills of exchange used by traders. The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","correct":"redeem","options":["redeem","exchange","collect","transport"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The End of Metal Currency","The Slow Spread of Paper Money","A Catalogue of Ancient Coins","How Central Banks Set Interest Rates"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Metal coins disappeared immediately after the first banknote.","Inflation has no relationship to the supply of paper notes.","Paper money emerged from private credit practices and failed when issuance outran reserves.","Paper money was invented by a single European monarch."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Resistance is not a future problem; it is the cumulative result of present habits."]}',
  '{"gapCorrect":"redeem","titleCorrectIndex":1,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."}',
  120,
  true
)
