INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-8',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"The Return of Beavers to River Valleys","passageText":"Beavers were hunted to near extinction in Europe, and their absence changed the shape of rivers. Without dams, streams ran faster and cut deeper channels, carrying sediment downstream and worsening floods. Reintroduction projects have produced a different landscape: ponds slow the water, raise the water table and create wetlands that hold carbon. Fish and amphibians return, and downstream towns receive less peak flow during storms. Farmers sometimes object when fields become wet, and roads can be flooded by an ambitious colony. Compensation schemes and carefully placed devices that regulate pond height have reduced the conflict. The beaver is therefore less a romantic symbol than a cheap piece of water infrastructure.","gapSentence":{"before":"Beavers were hunted to near extinction in Europe, and their absence changed the shape of rivers. Without dams, streams ran faster and cut deeper channels, carrying sediment downstream and worsening floods. Reintroduction projects have produced a different landscape: ponds slow the water, raise the water table and create wetlands that hold carbon. Fish and amphibians return, and downstream towns receive less peak flow during storms. Farmers sometimes object when fields become wet, and roads can be flooded by an ambitious colony. ","after":" schemes and carefully placed devices that regulate pond height have reduced the conflict. The beaver is therefore less a romantic symbol than a cheap piece of water infrastructure.","correct":"Compensation","options":["migration","education","Compensation","taxation"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Return of Beavers to River Valleys","How Dams Generate Electricity","A Field Guide to European Fish","The History of Fur Trading"],"correctIndex":0},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Beavers should be excluded from all agricultural land.","Reintroduction has no measurable effect on rivers.","Beaver dams increase downstream flooding in every case.","Beaver dams restore wetland hydrology and can reduce flood peaks at low cost."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The beaver is therefore less a romantic symbol than a cheap piece of water infrastructure.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve."]}',
  '{"gapCorrect":"Compensation","titleCorrectIndex":0,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"The beaver is therefore less a romantic symbol than a cheap piece of water infrastructure."}',
  120,
  true
)
