INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-12',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Theatre and Civic Life in Athens","passageText":"Athenian drama was funded by the state and attended by thousands of citizens, yet it was not simply entertainment. Tragedies staged arguments about justice, kinship and the limits of power in front of an audience that would later vote on war and taxation. Comedies mocked politicians by name while the city was at war. The theatre therefore functioned as a public rehearsal of civic dilemmas, and the festival calendar gave those dilemmas a recurring date. Attendance was not universal: women, slaves and foreigners occupied an ambiguous position in the audience. Still, the scale of the event made it one of the few places where a large community could share a vocabulary for debating what a good city should do.","gapSentence":{"before":"Athenian drama was funded by the state and attended by thousands of citizens, yet it was not simply entertainment. Tragedies staged arguments about justice, kinship and the limits of power in front of an audience that would later vote on war and taxation. Comedies mocked politicians by name while the city was at war. The theatre therefore functioned as a public rehearsal of ","after":" dilemmas, and the festival calendar gave those dilemmas a recurring date. Attendance was not universal: women, slaves and foreigners occupied an ambiguous position in the audience. Still, the scale of the event made it one of the few places where a large community could share a vocabulary for debating what a good city should do.","correct":"civic","options":["private","civic","social","rural"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Greek Sculpture in the Classical Period","Theatre and Civic Life in Athens","Roman Engineering and Aqueducts","The Origins of Opera"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Comedy avoided political subjects entirely.","Theatre had no connection to democratic decision-making.","Athenian theatre was a civic institution that rehearsed political dilemmas for a mass audience.","Athenian drama was performed only for the ruling elite."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Still, the scale of the event made it one of the few places where a large community could share a vocabulary for debating what a good city should do."]}',
  '{"gapCorrect":"civic","titleCorrectIndex":1,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Still, the scale of the event made it one of the few places where a large community could share a vocabulary for debating what a good city should do."}',
