INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-15',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Vertical Farming’s Energy Problem","passageText":"Vertical farms grow crops in stacked trays under artificial light, using a fraction of the land and almost no pesticides. Their advantage is greatest for leafy greens in cities, where transport distances are short and shelf life matters. The weakness is electricity. Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill prohibitive. Proponents argue that renewable tariffs and waste heat from nearby buildings can close the gap; critics note that those buildings are not always available and that batteries add further cost. The technology is therefore best understood as a specialised tool for a narrow range of crops rather than a general replacement for fields.","gapSentence":{"before":"Vertical farms grow crops in stacked trays under artificial light, using a fraction of the land and almost no pesticides. Their advantage is greatest for leafy greens in cities, where transport distances are short and shelf life matters. The weakness is electricity. Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill prohibitive. Proponents argue that renewable tariffs and waste heat from nearby buildings can close the gap; critics note that those buildings are not always available and that batteries add further cost. The technology is therefore best understood as a ","after":" tool for a narrow range of crops rather than a general replacement for fields.","correct":"specialised","options":["seasonal","manual","specialised","general"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Urban Food Markets","Vertical Farming’s Energy Problem","The History of Greenhouse Design","How LED Lighting Works"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Vertical farms suit leafy greens but are limited by the cost of artificial light.","Vertical farms can replace all field agriculture immediately.","Artificial lighting is cheaper than sunlight for every crop.","Energy costs are irrelevant to indoor farming."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill prohibitive.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","The effect is selective: emotionally charged material and skills practised the previous day benefit most."]}',
  '{"gapCorrect":"specialised","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"Sunlight is free, but lamps are not, and the intensity required for fruiting crops makes their energy bill prohibitive."}',
  120,
  true
)
