INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-16',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"How Archives Survive Fires","passageText":"Archives burn because paper burns, but the greater loss is often caused by water and smoke rather than flame. A fire in a library triggers sprinklers, and the books that survive the heat absorb water and develop mould within days. Conservators therefore plan for the whole sequence: detection, suppression, freezing and freeze-drying. Digitisation helps, but only for what has already been scanned, and scans rarely capture the material qualities that historians value. The most effective protection is duplication across distant sites, a practice that sounds bureaucratic until a single building is lost. Catastrophe planning is unglamorous work, and that is precisely why it is chronically underfunded.","gapSentence":{"before":"Archives burn because paper burns, but the greater loss is often caused by water and smoke rather than flame. A fire in a library triggers sprinklers, and the books that survive the heat absorb water and develop mould within days. Conservators therefore plan for the whole sequence: detection, suppression, freezing and freeze-drying. Digitisation helps, but only for what has already been scanned, and scans rarely capture the material qualities that historians value. The most effective protection is duplication across distant sites, a practice that sounds bureaucratic until a single building is lost. ","after":" planning is unglamorous work, and that is precisely why it is chronically underfunded.","correct":"Catastrophe","options":["Catastrophe","emergency","routine","financial"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Papermaking","How Archives Survive Fires","The Invention of the Printing Press","Modern Library Architecture"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Fires are the only threat to paper collections.","Archive survival depends on planning for water, mould and duplication, not only on fire suppression.","Sprinklers always save books without causing damage.","Digitisation fully replaces the need for physical archives."],"correctIndex":1},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Catastrophe planning is unglamorous work, and that is precisely why it is chronically underfunded.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."]}',
  '{"gapCorrect":"Catastrophe","titleCorrectIndex":1,"mainIdeaCorrectIndex":1,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"Catastrophe planning is unglamorous work, and that is precisely why it is chronically underfunded."}',
  120,
  true
)
