INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-21',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Light Pollution and the Vanishing Night Sky","passageText":"Street lighting makes cities safer and busier, but it also changes the sky. Light that escapes upwards is scattered by dust and water droplets, creating a glow that hides faint stars and disturbs nocturnal animals. Migrating birds can be drawn off course, moths exhaust themselves around lamps, and some trees delay leaf fall near bright streets. The problem is not brightness alone: the direction, colour and timing of light matter. Shields that point light downwards, warmer colours and switches that turn off after midnight reduce the effect at little cost. Dark skies are therefore not a demand to switch everything off, but a request to use light where and when it is actually needed.","gapSentence":{"before":"Street lighting makes cities safer and busier, but it also changes the sky. Light that escapes upwards is scattered by dust and water droplets, creating a glow that hides faint stars and disturbs nocturnal animals. Migrating birds can be drawn off course, moths exhaust themselves around lamps, and some trees delay leaf fall near bright streets. The problem is not brightness alone: the direction, colour and timing of light matter. ","after":" that point light downwards, warmer colours and switches that turn off after midnight reduce the effect at little cost. Dark skies are therefore not a demand to switch everything off, but a request to use light where and when it is actually needed.","correct":"Shields","options":["cables","windows","Shields","towers"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Biology of Moths","Why Cities Need Brighter Streets","Light Pollution and the Vanishing Night Sky","How Street Lamps Are Manufactured"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Light pollution is about direction, colour and timing as much as brightness.","Cities must remove all street lighting to protect wildlife.","Only the brightness of lamps affects the night sky.","Migrating birds are unaffected by artificial light."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Light that escapes upwards is scattered by dust and water droplets, creating a glow that hides faint stars and disturbs nocturnal animals.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most."]}',
  '{"gapCorrect":"Shields","titleCorrectIndex":2,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"Light that escapes upwards is scattered by dust and water droplets, creating a glow that hides faint stars and disturbs nocturnal animals."}',
  120,
  true
)
