INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-23',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Seed Banks as Insurance for Agriculture","passageText":"A seed bank looks like a library with very small books. Its purpose is to preserve genetic variety that farmers and breeders may need when diseases or climates change. Seeds are dried, sealed and stored at low temperature, and samples are tested periodically to check that they can still germinate. The work is slower than it appears: a single variety may need regeneration every few decades, which means growing it out, collecting fresh seed and avoiding cross-pollination. Seed banks cannot save everything, and they are a backup rather than a substitute for growing crops in fields. Still, the loss of a collection is permanent in a way that a failed harvest is not.","gapSentence":{"before":"A seed bank looks like a library with very small books. Its purpose is to preserve genetic variety that farmers and breeders may need when diseases or climates change. Seeds are dried, sealed and stored at low temperature, and samples are tested periodically to check that they can still germinate. The work is slower than it appears: a single variety may need regeneration every few decades, which means growing it out, collecting fresh seed and avoiding cross-","after":". Seed banks cannot save everything, and they are a backup rather than a substitute for growing crops in fields. Still, the loss of a collection is permanent in a way that a failed harvest is not.","correct":"pollination","options":["harvesting","storage","pollination","irrigation"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Farmers Abandon Old Varieties","Seed Banks as Insurance for Agriculture","How to Build a Greenhouse","The History of Wheat Breeding"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Stored seeds remain viable forever without testing.","Cross-pollination improves the accuracy of seed storage.","Seed banks preserve genetic options but require continual regeneration work.","Seed banks can replace the need to grow crops in fields."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Still, the loss of a collection is permanent in a way that a failed harvest is not."]}',
  '{"gapCorrect":"pollination","titleCorrectIndex":1,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Still, the loss of a collection is permanent in a way that a failed harvest is not."}',
  120,
  true
)
