INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-25',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"How Migrating Birds Combine Compasses","passageText":"Migrating birds find their way using more than one sense. Experiments with robins show that they can orient themselves by the Earth''s magnetic field, but they also use the sun, the stars and familiar landmarks. On cloudy nights, magnetic information becomes more important; on clear days, the position of the sun can override it. Young birds appear to learn a route by following adults and by memorising landscape features, while the magnetic sense provides a rough compass. The system is redundant by design, which is why removing a single cue rarely stops a migration. Navigation is not a single map but a set of overlapping instructions that can compensate when one is unavailable.","gapSentence":{"before":"Migrating birds find their way using more than one sense. Experiments with robins show that they can ","after":" themselves by the Earth''s magnetic field, but they also use the sun, the stars and familiar landmarks. On cloudy nights, magnetic information becomes more important; on clear days, the position of the sun can override it. Young birds appear to learn a route by following adults and by memorising landscape features, while the magnetic sense provides a rough compass. The system is redundant by design, which is why removing a single cue rarely stops a migration. Navigation is not a single map but a set of overlapping instructions that can compensate when one is unavailable.","correct":"orient","options":["rest","orient","feed","breed"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Birds Migrate South","The History of Ornithology","How Migrating Birds Combine Compasses","The Anatomy of Bird Wings"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Cloudy weather prevents all bird migration.","Young birds are born with a complete route map.","Birds navigate with overlapping cues that compensate for one another.","Birds rely on a single magnetic sense for all navigation."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Navigation is not a single map but a set of overlapping instructions that can compensate when one is unavailable."]}',
  '{"gapCorrect":"orient","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Navigation is not a single map but a set of overlapping instructions that can compensate when one is unavailable."}',
  120,
  true
)
