INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-30',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"Water Mills and Village Power","passageText":"Medieval water mills were not simply machines for grinding grain. They were legal and social arrangements as well. A mill required a weir, a channel and a pond, which changed the flow of the river and could flood a neighbour''s field. Lords who owned the mill often required tenants to use it and to pay a share of the flour, a practice that made milling a source of income as well as a service. Disputes over water rights appear in court records for centuries. The technology was modest, but its organisation shaped village life. Studying the mill therefore means studying property, labour and engineering at the same time.","gapSentence":{"before":"Medieval water mills were not simply machines for grinding grain. They were legal and social arrangements as well. A mill required a weir, a channel and a pond, which changed the flow of the river and could flood a neighbour''s field. Lords who owned the mill often required tenants to use it and to pay a share of the flour, a practice that made milling a source of income as well as a service. ","after":" over water rights appear in court records for centuries. The technology was modest, but its organisation shaped village life. Studying the mill therefore means studying property, labour and engineering at the same time.","correct":"Disputes","options":["machines","festivals","Disputes","harvests"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Invention of the Windmill","How Flour Is Refined","Medieval Farming Techniques","Water Mills and Village Power"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Medieval mills had no effect on river flow.","Tenants were never required to use a lord''s mill.","Milling was unrelated to property rights.","Water mills were social and legal institutions as well as machines."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Studying the mill therefore means studying property, labour and engineering at the same time."]}',
  '{"gapCorrect":"Disputes","titleCorrectIndex":3,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Studying the mill therefore means studying property, labour and engineering at the same time."}',
  120,
  true
)
