INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-32',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Terraces as Water Management","passageText":"Terraces turn a steep slope into a series of flat fields, but their purpose is not only to make planting easier. Each wall slows water running downhill, giving it time to soak into the soil instead of carrying it away. Over centuries, farmers in mountainous regions built terraces with stone, earth and local plants, and the structures became part of the landscape. When terraces are abandoned, the walls collapse and the soil erodes quickly. Modern restoration projects sometimes rebuild them with machines, which is faster but can compact the ground and damage the drainage that made the system work. The old design is not merely picturesque; it encodes practical knowledge about water.","gapSentence":{"before":"Terraces turn a steep slope into a series of flat fields, but their purpose is not only to make planting easier. Each wall slows water running downhill, giving it time to soak into the soil instead of carrying it away. Over centuries, farmers in mountainous regions built terraces with stone, earth and local plants, and the structures became part of the landscape. When terraces are abandoned, the walls collapse and the soil erodes quickly. Modern restoration projects sometimes rebuild them with machines, which is faster but can ","after":" the ground and damage the drainage that made the system work. The old design is not merely picturesque; it encodes practical knowledge about water.","correct":"compact","options":["fertilise","irrigate","compact","flood"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How to Build a Stone Wall","The Decline of Mountain Villages","Terraces as Water Management","The Geology of Mountains"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Terraces exist only to make slopes look attractive.","Abandoned terraces stabilize soil over time.","Machine-built terraces always improve drainage.","Terraces control water and soil, and their design carries practical knowledge."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","The old design is not merely picturesque; it encodes practical knowledge about water."]}',
  '{"gapCorrect":"compact","titleCorrectIndex":2,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"The old design is not merely picturesque; it encodes practical knowledge about water."}',
  120,
  true
)
