INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-33',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Chemistry of Natural Dyes","passageText":"Before synthetic colours, dyers worked with plants, insects and minerals, and the results were rarely simple. A red from madder changes with the mordant, a metal salt that fixes the dye to the fibre. Iron gives a dark, dull tone; alum gives a brighter one. The same bath can produce different shades on wool and cotton, and the water supply affects the outcome. Recipes were therefore guarded knowledge, passed between families and guilds. Synthetic dyes replaced them because they were cheaper and more predictable, not because the old colours were inferior. Modern craft dyers are rediscovering the variables that industrial chemistry removed, including the uncertainty that makes each batch distinct.","gapSentence":{"before":"Before synthetic colours, dyers worked with plants, insects and minerals, and the results were rarely simple. A red from madder changes with the mordant, a metal salt that fixes the dye to the fibre. Iron gives a dark, dull tone; alum gives a brighter one. The same bath can produce different shades on wool and cotton, and the water supply affects the outcome. Recipes were therefore guarded knowledge, passed between families and guilds. Synthetic dyes replaced them because they were cheaper and more predictable, not because the old colours were inferior. Modern craft dyers are rediscovering the ","after":" that industrial chemistry removed, including the uncertainty that makes each batch distinct.","correct":"variables","options":["workers","variables","machines","markets"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Synthetic Fibres","How Wool Is Spun","Why Natural Dyes Disappeared","The Chemistry of Natural Dyes"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Synthetic dyes produce different shades on every fibre.","Natural dyeing depended on chemistry and local conditions, making results variable.","Natural dyes were abandoned because their colours were always dull.","A mordant is a machine used to weave cloth."],"correctIndex":1},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Modern craft dyers are rediscovering the variables that industrial chemistry removed, including the uncertainty that makes each batch distinct.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."]}',
  '{"gapCorrect":"variables","titleCorrectIndex":3,"mainIdeaCorrectIndex":1,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"Modern craft dyers are rediscovering the variables that industrial chemistry removed, including the uncertainty that makes each batch distinct."}',
  120,
  true
)
