INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-35',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Forecasting Eruptions from Many Signals","passageText":"Predicting an eruption is not a single measurement but a pattern of them. Instruments record small earthquakes, changes in the shape of the ground and the composition of gases escaping from the crater. An increase in sulphur dioxide may suggest that magma is rising, while swelling of the surface indicates that pressure is building. None of these signals is reliable alone, and similar patterns can end without an eruption. Scientists therefore combine data with local knowledge and communicate uncertainty rather than a simple warning. False alarms are costly because they erode trust, yet a missed eruption is worse. Forecasting is a negotiation between evidence, timing and public patience.","gapSentence":{"before":"Predicting an eruption is not a single measurement but a pattern of them. Instruments record small earthquakes, changes in the shape of the ground and the composition of gases escaping from the crater. An increase in sulphur dioxide may suggest that magma is rising, while swelling of the surface indicates that pressure is building. None of these signals is reliable alone, and similar patterns can end without an eruption. Scientists therefore combine data with local knowledge and communicate ","after":" rather than a simple warning. False alarms are costly because they erode trust, yet a missed eruption is worse. Forecasting is a negotiation between evidence, timing and public patience.","correct":"uncertainty","options":["silence","speed","uncertainty","certainty"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Destructive Power of Lava","How Volcanoes Form Islands","The History of Seismology","Forecasting Eruptions from Many Signals"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["False alarms have no cost for public trust.","Ground swelling always means an eruption is certain.","Eruption forecasts combine several imperfect signals and must convey uncertainty.","A single gas measurement can predict every eruption."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The effect is selective: emotionally charged material and skills practised the previous day benefit most.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Forecasting is a negotiation between evidence, timing and public patience.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"uncertainty","titleCorrectIndex":3,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"Forecasting is a negotiation between evidence, timing and public patience."}',
  120,
  true
)
