INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-36',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"What Place Names Reveal About the Past","passageText":"Place names are often treated as labels, but they record older languages and older landscapes. A river called by a Celtic word may keep that name after the language itself has disappeared, because newcomers adopted the name from the people they displaced. Names can also describe features that no longer exist: a street may be named after a market that closed centuries ago. Linguists use these layers to reconstruct settlement patterns, and historians use them cautiously, because a name can be transferred from one place to another. The study is therefore a form of archaeology conducted through language, and it requires the same care about evidence and uncertainty.","gapSentence":{"before":"Place names are often treated as labels, but they record older languages and older landscapes. A river called by a Celtic word may keep that name after the language itself has disappeared, because newcomers adopted the name from the people they ","after":". Names can also describe features that no longer exist: a street may be named after a market that closed centuries ago. Linguists use these layers to reconstruct settlement patterns, and historians use them cautiously, because a name can be transferred from one place to another. The study is therefore a form of archaeology conducted through language, and it requires the same care about evidence and uncertainty.","correct":"displaced","options":["sheltered","displaced","employed","educated"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How Modern Maps Are Drawn","The Origins of Family Names","Why Languages Disappear","What Place Names Reveal About the Past"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Place names preserve linguistic and landscape history but must be read cautiously.","Place names always describe features that still exist.","Names disappear immediately when a language dies.","Place-name study is unrelated to settlement history."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","The study is therefore a form of archaeology conducted through language, and it requires the same care about evidence and uncertainty."]}',
  '{"gapCorrect":"displaced","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"The study is therefore a form of archaeology conducted through language, and it requires the same care about evidence and uncertainty."}',
  120,
  true
)
