INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-43',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"The Design of Flood Insurance","passageText":"Flood insurance is difficult because the risk is concentrated. A single storm can damage thousands of homes at once, so insurers cannot rely on the fact that most policyholders will not claim in the same year. Premiums that reflect the true risk would be unaffordable for the people living closest to rivers and coasts, and withdrawing cover would leave them without a market. Many governments therefore share the risk, subsidise premiums or require new buildings to meet flood standards. Each solution creates a different incentive: cheap insurance may encourage building in dangerous places, while strict pricing may push poor households out. The design of the scheme matters as much as the accuracy of the flood map.","gapSentence":{"before":"Flood insurance is difficult because the risk is concentrated. A single storm can damage thousands of homes at once, so insurers cannot rely on the fact that most policyholders will not claim in the same year. Premiums that reflect the true risk would be unaffordable for the people living closest to rivers and coasts, and withdrawing cover would leave them without a market. Many governments therefore share the risk, subsidise premiums or require new buildings to meet flood standards. Each solution creates a different ","after":": cheap insurance may encourage building in dangerous places, while strict pricing may push poor households out. The design of the scheme matters as much as the accuracy of the flood map.","correct":"incentive","options":["record","incentive","penalty","barrier"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of House Building","Why Maps Are Inaccurate","The Design of Flood Insurance","How Storms Form"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Flood insurance requires risk-sharing because losses are concentrated, and scheme design shapes behaviour.","Flood insurance is easy because claims are spread evenly over time.","Risk-based premiums are affordable for every household.","Flood maps alone determine the success of insurance."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The design of the scheme matters as much as the accuracy of the flood map.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve."]}',
  '{"gapCorrect":"incentive","titleCorrectIndex":2,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"The design of the scheme matters as much as the accuracy of the flood map."}',
  120,
  true
)
