INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-46',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"Digital Preservation Is Maintenance","passageText":"Digital files feel permanent because they can be copied without loss, yet copies are not the same as preservation. A format may become unreadable when the software that created it disappears, and a storage medium may fail silently. Archives therefore plan for migration: moving records to new formats and checking that nothing is lost in the process. Metadata is as important as the file itself, because a photograph without a date, owner or description is difficult to interpret later. The work is continuous, unlike the one-time act of placing a book on a shelf. A digital collection is less a building than a service that must be maintained, funded and tested.","gapSentence":{"before":"Digital files feel permanent because they can be copied without loss, yet copies are not the same as preservation. A format may become unreadable when the software that created it disappears, and a storage medium may fail silently. Archives therefore plan for migration: moving records to new formats and checking that nothing is lost in the process. Metadata is as important as the file itself, because a photograph without a date, owner or description is difficult to interpret later. The work is ","after":", unlike the one-time act of placing a book on a shelf. A digital collection is less a building than a service that must be maintained, funded and tested.","correct":"continuous","options":["temporary","manual","continuous","optional"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of the Library","How Hard Drives Store Data","Why Paper Is Obsolete","Digital Preservation Is Maintenance"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Digital copies remain readable without maintenance.","Metadata is unnecessary once a file is copied.","Preservation ends when a file is placed on a drive.","Digital archives require continual format migration and metadata, not one-time storage."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Archives therefore plan for migration: moving records to new formats and checking that nothing is lost in the process.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"continuous","titleCorrectIndex":3,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"Archives therefore plan for migration: moving records to new formats and checking that nothing is lost in the process."}',
  120,
  true
)
