INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-50',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Community Land Trusts and Lasting Affordability","passageText":"A community land trust separates the ownership of land from the ownership of the building on it. The trust keeps the land in permanent community ownership and sells or leases the home at a price that excludes speculative gain. Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises. The model protects public investment, but it also limits what an owner can gain, which makes it unattractive to some buyers. It works best where land is expensive and public subsidy is available. The trust is therefore not a general solution to housing costs, but a way to make a subsidy last longer than one sale.","gapSentence":{"before":"A community land trust separates the ownership of land from the ownership of the building on it. The trust keeps the land in permanent community ownership and sells or leases the home at a price that excludes speculative gain. Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises. The model protects public investment, but it also limits what an owner can gain, which makes it unattractive to some buyers. It works best where land is expensive and public ","after":" is available. The trust is therefore not a general solution to housing costs, but a way to make a subsidy last longer than one sale.","correct":"subsidy","options":["subsidy","market","tenant","street"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How Mortgages Are Calculated","Why Rents Always Rise","Community Land Trusts and Lasting Affordability","The History of Home Ownership"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Community land trusts allow unlimited speculative gain.","The model works equally well in every housing market.","Public subsidy is irrelevant to land trusts.","Community land trusts preserve affordability by separating land from building ownership."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most."]}',
  '{"gapCorrect":"subsidy","titleCorrectIndex":2,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"Buyers agree to resell to another eligible household at a formula set in advance, so the home stays affordable when the market rises."}',
