INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-52',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"Why Open-Plan Offices Are Noisy","passageText":"Open-plan offices are designed to encourage conversation, but they often make focused work harder. Sound travels across desks, and speech is especially distracting because the brain automatically processes meaning. Background music or white noise can mask some of it, but the effect depends on the task and the person. Acoustic panels, carpets and soft furniture absorb reflections, while screens and plants break lines of sight. The most effective solution is often organisational: placing teams that talk together near each other and quiet tasks in a separate room. A design that ignores the type of work being done will produce complaints even if the furniture is expensive.","gapSentence":{"before":"Open-plan offices are designed to encourage conversation, but they often make focused work harder. Sound travels across desks, and speech is especially distracting because the brain automatically processes meaning. Background music or white noise can mask some of it, but the effect depends on the task and the person. Acoustic panels, carpets and soft furniture absorb reflections, while screens and plants break lines of sight. The most effective solution is often ","after":": placing teams that talk together near each other and quiet tasks in a separate room. A design that ignores the type of work being done will produce complaints even if the furniture is expensive.","correct":"organisational","options":["musical","organisational","technical","seasonal"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Office Furniture","How to Design a Library","The Economics of Remote Work","Why Open-Plan Offices Are Noisy"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Expensive furniture guarantees a quiet office.","Open-plan noise is best managed by matching layout to the kind of work being done.","Open-plan offices always improve concentration.","Acoustic panels eliminate all speech distraction."],"correctIndex":1},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Sound travels across desks, and speech is especially distracting because the brain automatically processes meaning."]}',
  '{"gapCorrect":"organisational","titleCorrectIndex":3,"mainIdeaCorrectIndex":1,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Sound travels across desks, and speech is especially distracting because the brain automatically processes meaning."}',
  120,
  true
)
