INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-56',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Why Names Are Hard to Remember","passageText":"Forgetting a name is not usually a sign that memory is failing in general. Names are arbitrary labels attached to people, and they carry little meaning that would help retrieval. A face, a voice and a context are stored in rich detail, but the name is a thin link to that bundle. Retrieval also depends on attention at the moment of learning: a name heard in a noisy room may never be encoded properly. Strategies that work include repeating the name, linking it to an image and using it soon afterwards. The experience of having a name on the tip of the tongue is a retrieval failure, not evidence that the information has vanished.","gapSentence":{"before":"Forgetting a name is not usually a sign that memory is failing in general. Names are arbitrary labels attached to people, and they carry little meaning that would help ","after":". A face, a voice and a context are stored in rich detail, but the name is a thin link to that bundle. Retrieval also depends on attention at the moment of learning: a name heard in a noisy room may never be encoded properly. Strategies that work include repeating the name, linking it to an image and using it soon afterwards. The experience of having a name on the tip of the tongue is a retrieval failure, not evidence that the information has vanished.","correct":"retrieval","options":["travel","retrieval","storage","design"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Anatomy of the Brain","How to Improve Exam Scores","The History of Surnames","Why Names Are Hard to Remember"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Forgetting a name proves that memory is declining.","Names are stored with more meaning than faces.","Tip-of-the-tongue states mean the memory is gone.","Names are hard to recall because they are arbitrary labels with weak retrieval cues."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","The experience of having a name on the tip of the tongue is a retrieval failure, not evidence that the information has vanished.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"retrieval","titleCorrectIndex":3,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"The experience of having a name on the tip of the tongue is a retrieval failure, not evidence that the information has vanished."}',
  120,
  true
)
