INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-62',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Why Rivers Meander","passageText":"Rivers rarely run in straight lines. Once a slight bend appears, water moves faster along the outer bank and slower along the inner one. The faster current erodes the outer bank, while the slower current drops sand and gravel on the inside. The bend therefore grows until the river doubles back on itself. In a flood, the water may cut across the narrow neck and leave the old loop as an oxbow lake. Engineers who straighten a river for navigation often find that the problem returns downstream, because the extra speed has to go somewhere. Restoration projects now work with the curve rather than against it, planting banks and reconnecting floodplain channels.","gapSentence":{"before":"Rivers rarely run in straight lines. Once a slight bend appears, water moves faster along the outer bank and slower along the inner one. The faster current ","after":" the outer bank, while the slower current drops sand and gravel on the inside. The bend therefore grows until the river doubles back on itself. In a flood, the water may cut across the narrow neck and leave the old loop as an oxbow lake. Engineers who straighten a river for navigation often find that the problem returns downstream, because the extra speed has to go somewhere. Restoration projects now work with the curve rather than against it, planting banks and reconnecting floodplain channels.","correct":"erodes","options":["cools","erodes","deposits","widens"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Chemistry of Drinking Water","How to Predict Rainfall","Why Rivers Meander","A Guide to Building Dams"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Oxbow lakes are created by engineers during navigation works.","River bends grow through uneven erosion and deposition, and straightening them creates new problems downstream.","Rivers are straight unless humans make them curve.","Meanders form because water slows down on the outer bank."],"correctIndex":1},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Engineers who straighten a river for navigation often find that the problem returns downstream, because the extra speed has to go somewhere."]}',
  '{"gapCorrect":"erodes","titleCorrectIndex":2,"mainIdeaCorrectIndex":1,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Engineers who straighten a river for navigation often find that the problem returns downstream, because the extra speed has to go somewhere."}',
  120,
  true
)
