INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-63',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Engineering of a Canal Lock","passageText":"A canal lock is a water staircase. It has two gates and a chamber just long enough for a boat. When the boat enters, the downstream gate closes and a valve lets water in from the upper level. The boat rises with the water, and the upstream gate opens. Going downhill reverses the sequence. Each passage uses a large volume of water, so many canals have side reservoirs that refill the chamber between boats. The gates must seal tightly, because a small leak wastes water all day and can make the lock slow. Maintenance crews inspect the timber, the hinges and the valves, often while the canal is closed for the winter.","gapSentence":{"before":"A canal lock is a water staircase. It has two gates and a chamber just long enough for a boat. When the boat enters, the downstream gate closes and a valve lets water in from the upper level. The boat rises with the water, and the upstream gate opens. Going downhill reverses the sequence. Each passage uses a large volume of water, so many canals have side ","after":" that refill the chamber between boats. The gates must seal tightly, because a small leak wastes water all day and can make the lock slow. Maintenance crews inspect the timber, the hinges and the valves, often while the canal is closed for the winter.","correct":"reservoirs","options":["towers","reservoirs","pumps","bridges"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Engineering of a Canal Lock","The History of Steam Ships","How to Build a Garden Pond","Why Rivers Flood"],"correctIndex":0},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["A lock moves boats between water levels by controlling the flow into and out of a sealed chamber.","Locks work by lifting boats with a crane.","Canal locks require no maintenance because they have no moving parts.","Water loss in a lock is impossible because the gates are always open."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","The gates must seal tightly, because a small leak wastes water all day and can make the lock slow.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"reservoirs","titleCorrectIndex":0,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"The gates must seal tightly, because a small leak wastes water all day and can make the lock slow."}',
  120,
  true
)
