INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-65',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"The History of the Modern Calendar","passageText":"The calendar on a wall is a compromise between astronomy and administration. A solar year is not a whole number of days, and a lunar month is not a simple fraction of a year. Early reformers added extra months when the seasons drifted, which made planning difficult. The system used today inserts a leap day almost every four years, but skips it in most century years. That rule keeps the calendar within a day of the seasons for thousands of years. The change was not only mathematical: adopting it required governments to agree, and some countries resisted for centuries. A shared calendar is therefore an instrument of coordination as much as a record of time.","gapSentence":{"before":"The calendar on a wall is a compromise between astronomy and administration. A solar year is not a whole number of days, and a lunar month is not a simple fraction of a year. Early reformers added extra months when the seasons drifted, which made planning difficult. The system used today inserts a leap day almost every four years, but skips it in most century years. That rule keeps the calendar within a day of the seasons for thousands of years. The change was not only mathematical: adopting it required governments to agree, and some countries resisted for centuries. A shared calendar is therefore an instrument of ","after":" as much as a record of time.","correct":"coordination","options":["competition","decoration","transport","coordination"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Time Zones Disappeared","The History of the Modern Calendar","How to Read a Sundial","The Physics of the Moon"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Every country adopted the modern calendar at the same time.","The modern calendar resolves an astronomical mismatch through a political agreement on leap years.","The calendar is a perfect measurement of the solar year.","Leap years exist because the moon orbits the Earth every 365 days."],"correctIndex":1},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","A solar year is not a whole number of days, and a lunar month is not a simple fraction of a year."]}',
  '{"gapCorrect":"coordination","titleCorrectIndex":1,"mainIdeaCorrectIndex":1,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"A solar year is not a whole number of days, and a lunar month is not a simple fraction of a year."}',
  120,
  true
)
