INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-66',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Ecology of Roadside Verges","passageText":"Roadside verges are often mown to look tidy, yet their value depends on leaving plants standing. A strip of native grass and flowers feeds bees, shelters beetles and holds soil during heavy rain. Frequent cutting removes flowers before they seed and favours a few aggressive grasses. Councils that mow once or twice a year, and remove the cuttings, see more species return. The change can look untidy at first, so several projects put up small signs explaining the purpose. Verges also need protection from salt, litter and soil dumped by contractors. Management is therefore a matter of timing: cut late enough for seeds to set, but early enough to prevent scrub from taking over.","gapSentence":{"before":"Roadside ","after":" are often mown to look tidy, yet their value depends on leaving plants standing. A strip of native grass and flowers feeds bees, shelters beetles and holds soil during heavy rain. Frequent cutting removes flowers before they seed and favours a few aggressive grasses. Councils that mow once or twice a year, and remove the cuttings, see more species return. The change can look untidy at first, so several projects put up small signs explaining the purpose. Verges also need protection from salt, litter and soil dumped by contractors. Management is therefore a matter of timing: cut late enough for seeds to set, but early enough to prevent scrub from taking over.","correct":"verges","options":["roofs","bridges","verges","gardens"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How to Design a Motorway","The Chemistry of Road Salt","Why Lawns Need Water","The Ecology of Roadside Verges"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Native flowers grow best when all cuttings are left in place.","Verges have no ecological value because they are beside roads.","Roadside verges support biodiversity when cutting is timed to let plants seed and scrub is controlled.","Roadside verges should be mown weekly to protect insects."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","A strip of native grass and flowers feeds bees, shelters beetles and holds soil during heavy rain.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"verges","titleCorrectIndex":3,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"A strip of native grass and flowers feeds bees, shelters beetles and holds soil during heavy rain."}',
  120,
  true
)
