INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-68',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"The Chemistry of Stainless Steel","passageText":"Iron rusts because oxygen and water reach its surface and form a flaking oxide. Stainless steel resists this not by excluding oxygen but by using it. Chromium in the alloy reacts first and creates a thin, stable layer that seals the metal beneath. If the surface is scratched, the layer repairs itself provided that oxygen is available. Carbon is a complication: too much of it combines with chromium and leaves the surrounding metal vulnerable. The alloy therefore needs careful control during production. Stainless steel is not indestructible. Chloride from seawater can break the protective layer, which is why marine fittings use a different grade and why even a good sink stains if bleach is left on it.","gapSentence":{"before":"Iron rusts because oxygen and water reach its surface and form a flaking oxide. Stainless steel resists this not by excluding oxygen but by using it. Chromium in the ","after":" reacts first and creates a thin, stable layer that seals the metal beneath. If the surface is scratched, the layer repairs itself provided that oxygen is available. Carbon is a complication: too much of it combines with chromium and leaves the surrounding metal vulnerable. The alloy therefore needs careful control during production. Stainless steel is not indestructible. Chloride from seawater can break the protective layer, which is why marine fittings use a different grade and why even a good sink stains if bleach is left on it.","correct":"alloy","options":["furnace","alloy","mixture","coating"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of the Fork","Why Metal Conducts Heat","The Chemistry of Stainless Steel","How Iron Ore Is Mined"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Stainless steel is immune to rust because it contains no iron.","Carbon improves the protective layer and makes the alloy stronger.","Seawater has no effect on any grade of stainless steel.","Stainless steel protects itself with a chromium oxide layer that can be damaged by chloride."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The effect is selective: emotionally charged material and skills practised the previous day benefit most.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Chromium in the alloy reacts first and creates a thin, stable layer that seals the metal beneath.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms."]}',
  '{"gapCorrect":"alloy","titleCorrectIndex":2,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"Chromium in the alloy reacts first and creates a thin, stable layer that seals the metal beneath."}',
  120,
  true
)
