INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-70',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"The Design of Subway Maps","passageText":"A subway map is a diagram, not a survey. Its purpose is to show how lines connect, so geography is stretched and compressed to make the routes readable. Stations are spaced evenly, and lines run at fixed angles. This distortion is deliberate: a passenger needs to know where to change, not how far the tunnel curves. Colour and symbols carry the same information for people who cannot read the labels. Designers test a map by asking travellers to plan a journey, not by measuring distances. The best maps balance clarity with honesty, and they include a note when the scale is not uniform. A map that looks accurate but confuses the passenger has failed at its only job.","gapSentence":{"before":"A subway map is a diagram, not a survey. Its purpose is to show how lines connect, so geography is stretched and compressed to make the routes readable. Stations are spaced evenly, and lines run at fixed angles. This distortion is deliberate: a passenger needs to know where to change, not how far the tunnel curves. Colour and symbols carry the same information for people who cannot read the labels. Designers test a map by asking travellers to plan a journey, not by measuring distances. The best maps balance clarity with honesty, and they include a note when the scale is not ","after":". A map that looks accurate but confuses the passenger has failed at its only job.","correct":"uniform","options":["visible","accurate","uniform","constant"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Economics of Ticket Prices","The Design of Subway Maps","The History of Underground Railways","How to Read a Topographic Map"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["A good subway map should preserve distances exactly.","Station spacing on a subway map must match the real tunnel.","Colour and symbols are decorative and carry no information.","A transit map deliberately distorts geography to make connections and changes easy to read."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","A map that looks accurate but confuses the passenger has failed at its only job.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage."]}',
  '{"gapCorrect":"uniform","titleCorrectIndex":1,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"A map that looks accurate but confuses the passenger has failed at its only job."}',
  120,
  true
)
