INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-71',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"How a Water Filter Works","passageText":"A household water filter usually combines two mechanisms. A fine membrane or ceramic element traps particles that are too large to pass, while activated carbon adsorbs dissolved chemicals that give water a taste or colour. The carbon has a limited capacity: once its surface is full, it stops working and may release what it captured. Filters therefore need replacement at the interval stated by the manufacturer, not merely when the flow slows. A filter can also become a home for bacteria if it is left wet and unused for weeks. No domestic device sterilises water reliably, so a filter should not be treated as a substitute for boiling when a supply is known to be contaminated.","gapSentence":{"before":"A household water filter usually combines two mechanisms. A fine membrane or ceramic element traps particles that are too large to pass, while activated carbon adsorbs dissolved chemicals that give water a taste or colour. The carbon has a limited ","after":": once its surface is full, it stops working and may release what it captured. Filters therefore need replacement at the interval stated by the manufacturer, not merely when the flow slows. A filter can also become a home for bacteria if it is left wet and unused for weeks. No domestic device sterilises water reliably, so a filter should not be treated as a substitute for boiling when a supply is known to be contaminated.","correct":"capacity","options":["pressure","colour","weight","capacity"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How a Water Filter Works","The History of Plumbing","Why Rivers Freeze","How to Build a Rain Barrel"],"correctIndex":0},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Activated carbon can be used forever without replacement.","A filter improves taste but never removes particles.","Filters combine physical trapping and adsorption, have a limited life and do not sterilise water.","A water filter removes every microorganism from any supply."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","A fine membrane or ceramic element traps particles that are too large to pass, while activated carbon adsorbs dissolved chemicals that give water a taste or colour."]}',
  '{"gapCorrect":"capacity","titleCorrectIndex":0,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"A fine membrane or ceramic element traps particles that are too large to pass, while activated carbon adsorbs dissolved chemicals that give water a taste or colour."}',
