INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-72',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Geology of Hot Springs","passageText":"Hot springs occur where groundwater descends deep enough to be heated by rock and then returns to the surface. The water may travel for decades, dissolving minerals along the way. At the surface, cooling changes the chemistry, and the dissolved material precipitates as colourful terraces or fine sinter. The temperature and flow depend on the plumbing below, which is why a spring can change after an earthquake. Microbes that thrive in hot water add another layer: their pigments colour the pools and their metabolism alters the minerals. Visitors are asked to stay on boardwalks not only to protect the formations but also because the crust above a spring can be thin and dangerously hot.","gapSentence":{"before":"Hot springs occur where groundwater descends deep enough to be heated by rock and then returns to the surface. The water may travel for decades, dissolving minerals along the way. At the surface, cooling changes the chemistry, and the dissolved material ","after":" as colourful terraces or fine sinter. The temperature and flow depend on the plumbing below, which is why a spring can change after an earthquake. Microbes that thrive in hot water add another layer: their pigments colour the pools and their metabolism alters the minerals. Visitors are asked to stay on boardwalks not only to protect the formations but also because the crust above a spring can be thin and dangerously hot.","correct":"precipitates","options":["melts","floats","precipitates","dissolves"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Volcanoes Erupt","The Geology of Hot Springs","How to Build a Swimming Pool","The Chemistry of Soap"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Hot springs are caused by rainwater boiling on the surface.","The chemistry of a hot spring never changes over time.","Boardwalks exist only to keep visitors comfortable.","Hot springs form when deep groundwater is heated and returns, depositing minerals and supporting heat-loving microbes."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Hot springs occur where groundwater descends deep enough to be heated by rock and then returns to the surface."]}',
  '{"gapCorrect":"precipitates","titleCorrectIndex":1,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Hot springs occur where groundwater descends deep enough to be heated by rock and then returns to the surface."}',
  120,
  true
)
