INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-73',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"The Invention of Braille","passageText":"Braille represents letters with raised dots, but its power comes from the way the dots are grouped. A six-dot cell can be read with one fingertip, and the same cell can also encode music, mathematics or a foreign alphabet. The system was developed by a student who had lost his sight and who understood that touch needs patterns, not miniature shapes. Production was once slow and expensive; modern embossers and refreshable displays have changed access, though most screens still cannot show a diagram. Learning braille takes time, and many adults lose the skill through lack of practice. Its survival depends on teachers, on labelled packaging and on the expectation that blind people will read, not only listen.","gapSentence":{"before":"Braille represents letters with raised dots, but its power comes from the way the dots are grouped. A six-dot ","after":" can be read with one fingertip, and the same cell can also encode music, mathematics or a foreign alphabet. The system was developed by a student who had lost his sight and who understood that touch needs patterns, not miniature shapes. Production was once slow and expensive; modern embossers and refreshable displays have changed access, though most screens still cannot show a diagram. Learning braille takes time, and many adults lose the skill through lack of practice. Its survival depends on teachers, on labelled packaging and on the expectation that blind people will read, not only listen.","correct":"cell","options":["line","frame","cell","page"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How the Eye Works","The Design of Public Signs","The Invention of Braille","A History of Printing"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Refreshable displays have made braille teachers unnecessary.","Braille can only represent the Latin alphabet.","Braille encodes language as tactile patterns and remains dependent on teaching and accessible design.","Braille is simply a set of miniature printed letters."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","A six-dot cell can be read with one fingertip, and the same cell can also encode music, mathematics or a foreign alphabet.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","The effect is selective: emotionally charged material and skills practised the previous day benefit most."]}',
  '{"gapCorrect":"cell","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":1,"highlightCorrectSubstring":"A six-dot cell can be read with one fingertip, and the same cell can also encode music, mathematics or a foreign alphabet."}',
  120,
  true
)
