INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-80',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"The Physics of a Curling Stone","passageText":"A curling stone travels down the ice with a slow rotation, and the path it takes seems to defy intuition. Friction melts a thin film of water beneath the running band, and the stone curves because the front edge experiences more resistance than the back. Sweeping does not simply warm the ice. It removes frost and small debris, and it briefly reduces friction so the stone runs farther and straighter. The skip reads the speed and the line, then decides whether to sweep or to leave the stone alone. Players cannot steer the stone directly; they can only influence the ice ahead of it. The sport is therefore a conversation between thrower, sweepers and the surface itself.","gapSentence":{"before":"A curling stone travels down the ice with a slow ","after":", and the path it takes seems to defy intuition. Friction melts a thin film of water beneath the running band, and the stone curves because the front edge experiences more resistance than the back. Sweeping does not simply warm the ice. It removes frost and small debris, and it briefly reduces friction so the stone runs farther and straighter. The skip reads the speed and the line, then decides whether to sweep or to leave the stone alone. Players cannot steer the stone directly; they can only influence the ice ahead of it. The sport is therefore a conversation between thrower, sweepers and the surface itself.","correct":"rotation","options":["colour","rotation","speed","weight"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["A History of Winter Sports","How Ice Rinks Are Built","The Chemistry of Salt","The Physics of a Curling Stone"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Players control the stone with a hidden handle.","Curling stones curve through asymmetric friction, and sweeping changes the ice rather than steering the stone.","Sweeping directly pushes the stone sideways.","A curling stone travels in a straight line regardless of rotation."],"correctIndex":1},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","The sport is therefore a conversation between thrower, sweepers and the surface itself.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"rotation","titleCorrectIndex":3,"mainIdeaCorrectIndex":1,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"The sport is therefore a conversation between thrower, sweepers and the surface itself."}',
  120,
  true
)
