INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-82',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"The Rise of the QR Code","passageText":"A QR code packs data into a square grid of black and white modules. Unlike a barcode, it can be read in two directions, so it holds far more information in a small space. Error correction is built in: part of the pattern can be damaged or covered and the scanner can still recover the message. That robustness made the code useful on posters, tickets and parcels, where printing is imperfect. The same features create risks. A sticker can cover a legitimate code with another that leads to a fraudulent site, and a code can track who scanned it. Users should check the address before paying, and organisers should place codes where they cannot be easily replaced.","gapSentence":{"before":"A QR code packs data into a square grid of black and white ","after":". Unlike a barcode, it can be read in two directions, so it holds far more information in a small space. Error correction is built in: part of the pattern can be damaged or covered and the scanner can still recover the message. That robustness made the code useful on posters, tickets and parcels, where printing is imperfect. The same features create risks. A sticker can cover a legitimate code with another that leads to a fraudulent site, and a code can track who scanned it. Users should check the address before paying, and organisers should place codes where they cannot be easily replaced.","correct":"modules","options":["pixels","frames","modules","cells"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Paper Money","How Barcodes Were Invented","The Design of Board Games","The Rise of the QR Code"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["QR codes store data in two dimensions and survive damage, but their convenience also enables fraud and tracking.","QR codes hold less information than a standard barcode.","A damaged QR code can never be scanned.","QR codes cannot be used to track individual users."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","Unlike a barcode, it can be read in two directions, so it holds far more information in a small space."]}',
  '{"gapCorrect":"modules","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Unlike a barcode, it can be read in two directions, so it holds far more information in a small space."}',
  120,
  true
)
