INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-83',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"How a Pacemaker Regulates the Heart","passageText":"A pacemaker keeps the heart beating at a safe rate when its natural electrical signal fails. A small generator sends pulses through leads to the heart muscle, and sensors adjust the rate as the body moves. Modern devices can also record rhythms, which helps a doctor identify a problem that occurs between appointments. The battery lasts for years, but it cannot be replaced on its own; the generator is exchanged in a short operation. Leads are the delicate part, because they pass through a moving vein and can fracture or become infected. Remote monitoring reduces some risks but creates a stream of data that someone must review. A device is only as good as the follow-up it receives.","gapSentence":{"before":"A pacemaker keeps the heart beating at a safe rate when its natural electrical signal fails. A small generator sends ","after":" through leads to the heart muscle, and sensors adjust the rate as the body moves. Modern devices can also record rhythms, which helps a doctor identify a problem that occurs between appointments. The battery lasts for years, but it cannot be replaced on its own; the generator is exchanged in a short operation. Leads are the delicate part, because they pass through a moving vein and can fracture or become infected. Remote monitoring reduces some risks but creates a stream of data that someone must review. A device is only as good as the follow-up it receives.","correct":"pulses","options":["signals","cells","pulses","valves"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Physics of Sound","How a Pacemaker Regulates the Heart","The History of Surgery","How Muscles Grow"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["A pacemaker replaces the heart with a mechanical pump.","Pacemaker batteries can be recharged without an operation.","Remote monitoring removes the need for any clinical review.","A pacemaker adjusts electrical pulses to the heart and depends on lead integrity and regular follow-up."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A device is only as good as the follow-up it receives.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks."]}',
  '{"gapCorrect":"pulses","titleCorrectIndex":1,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"A device is only as good as the follow-up it receives."}',
  120,
  true
)
