INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-84',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Secret Life of Soil Fungi","passageText":"Beneath a forest floor, fungal threads connect roots to soil particles and to one another. The fungus receives sugars from the tree and supplies water and minerals in return. Some networks link different trees, allowing carbon to move between them, although the size and importance of this exchange are still debated. Fungi also decompose dead matter, releasing nutrients that would otherwise stay locked in leaves and wood. Ploughing, compaction and fungicides can break these threads, and a field may take years to recover. Farmers who reduce tillage and keep living roots in the ground are, in effect, feeding the network. The soil is not an inert medium; it is a living infrastructure that supports the crop above.","gapSentence":{"before":"Beneath a forest floor, fungal threads connect roots to soil particles and to one another. The fungus receives sugars from the tree and supplies water and minerals in return. Some networks link different trees, allowing carbon to move between them, although the size and importance of this exchange are still debated. Fungi also decompose dead matter, releasing nutrients that would otherwise stay locked in leaves and wood. Ploughing, compaction and fungicides can break these threads, and a field may take years to recover. Farmers who reduce ","after":" and keep living roots in the ground are, in effect, feeding the network. The soil is not an inert medium; it is a living infrastructure that supports the crop above.","correct":"tillage","options":["transport","tillage","harvest","storage"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["Why Forests Are Cut Down","The Secret Life of Soil Fungi","How to Compost at Home","The Structure of a Leaf"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Soil fungi only decompose dead wood and never interact with roots.","Ploughing improves fungal networks by aerating the soil.","All carbon in a forest moves only through the air.","Mycorrhizal fungi trade minerals and water for sugars and are damaged by soil disturbance."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","The fungus receives sugars from the tree and supplies water and minerals in return.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms."]}',
  '{"gapCorrect":"tillage","titleCorrectIndex":1,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"The fungus receives sugars from the tree and supplies water and minerals in return."}',
  120,
  true
)
