INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-86',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"Why Wooden Ships Leak","passageText":"A wooden ship leaks because wood moves. Planks swell when wet and shrink when dry, so a hull that is tight at sea may open at the seams in harbour. Traditional builders left gaps that caulking could fill with tar and fibre, and crews pumped the bilge regularly. The pumps were not a sign of failure; they were part of normal operation. Rot was the greater danger, because fresh water trapped below deck encouraged fungi that quietly weakened the structure. Ventilation and washing with salt water helped, but inspection required access to spaces that were cramped and dark. A ship was maintained by constant attention, not by a single repair.","gapSentence":{"before":"A wooden ship leaks because wood moves. Planks swell when wet and shrink when dry, so a hull that is tight at sea may open at the seams in harbour. Traditional builders left gaps that caulking could fill with tar and fibre, and crews pumped the bilge regularly. The pumps were not a sign of failure; they were part of normal operation. Rot was the greater danger, because fresh water trapped below deck encouraged fungi that quietly weakened the structure. ","after":" and washing with salt water helped, but inspection required access to spaces that were cramped and dark. A ship was maintained by constant attention, not by a single repair.","correct":"Ventilation","options":["Ventilation","heating","lighting","ballast"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Navigation","How to Build a Canoe","The Physics of Waves","Why Wooden Ships Leak"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Wooden hulls leak because planks move with moisture, and maintenance must control water and rot.","Wooden ships never leak once they are launched.","Bilge pumps are only used when a ship is sinking.","Fresh water below deck protects wood from decay."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve.","A ship was maintained by constant attention, not by a single repair.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms."]}',
  '{"gapCorrect":"Ventilation","titleCorrectIndex":3,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"A ship was maintained by constant attention, not by a single repair."}',
  120,
  true
)
