INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-88',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"How Sirens Carry Over Water","passageText":"Sound travels faster in warm air than in cold air, and this difference bends a siren away from the ground on a hot day. A warning that is loud at the source may be faint a few streets away, especially over water where the temperature layers are sharp. Tests therefore measure sound at the positions where people actually live, not only at the siren. Wind and buildings add further variation, and a valley can focus or scatter the noise. Modern systems use several locations and multiple tones so that no single failure leaves an area silent. A siren is not a guarantee of reach; it is one link in a chain that includes phones, radio and trusted local messengers.","gapSentence":{"before":"Sound travels faster in warm air than in cold air, and this difference bends a siren away from the ground on a hot day. A warning that is loud at the source may be faint a few streets away, especially over water where the temperature layers are sharp. Tests therefore measure sound at the positions where people actually live, not only at the siren. Wind and buildings add further variation, and a valley can focus or scatter the noise. Modern systems use several locations and multiple tones so that no single failure leaves an area silent. A siren is not a guarantee of reach; it is one link in a ","after":" that includes phones, radio and trusted local messengers.","correct":"chain","options":["tower","bell","signal","chain"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How to Build a Speaker","Why the Sea Is Salty","How Sirens Carry Over Water","The History of Radio"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Sound travels more slowly in warm air than in cold air.","One siren is enough to warn an entire region in every condition.","Temperature layers bend sound, so siren coverage must be measured where people live and backed by other channels.","A siren is equally audible everywhere regardless of weather."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A siren is not a guarantee of reach; it is one link in a chain that includes phones, radio and trusted local messengers.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve."]}',
  '{"gapCorrect":"chain","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"A siren is not a guarantee of reach; it is one link in a chain that includes phones, radio and trusted local messengers."}',
  120,
  true
)
