INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-89',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"The Problem with Plastic Recycling","passageText":"Plastic recycling is limited by chemistry. Each polymer has its own melting point and properties, and mixing them produces a weak material. Collection also brings food, labels and moisture, so sorting must be thorough. Even a clean stream degrades each time it is melted, which is why recycled plastic often becomes a bench or a bin rather than a bottle. Markets matter as much as technology: if oil is cheap, new plastic undercuts the recycled product, and a town may find that its carefully sorted bales have nowhere to go. The honest response is to reduce unnecessary packaging and design products for disassembly, not to assume that a recycling symbol solves the problem.","gapSentence":{"before":"Plastic recycling is limited by chemistry. Each polymer has its own melting point and properties, and mixing them produces a weak material. Collection also brings food, labels and moisture, so sorting must be thorough. Even a clean stream ","after":" each time it is melted, which is why recycled plastic often becomes a bench or a bin rather than a bottle. Markets matter as much as technology: if oil is cheap, new plastic undercuts the recycled product, and a town may find that its carefully sorted bales have nowhere to go. The honest response is to reduce unnecessary packaging and design products for disassembly, not to assume that a recycling symbol solves the problem.","correct":"degrades","options":["improves","expands","floats","degrades"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How to Make Glass","Why Landfills Smell","The Problem with Plastic Recycling","The History of Oil"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Recycled plastic is always cheaper than new plastic.","A recycling symbol guarantees that an item will be recycled.","Plastic recycling is constrained by mixed polymers, degradation and weak markets, so reduction and design matter.","All plastics can be melted together into a strong material."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Each polymer has its own melting point and properties, and mixing them produces a weak material.","Leaves also release water vapour, cooling the air around a street by several degrees and lowering the electricity demand of nearby buildings."]}',
  '{"gapCorrect":"degrades","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"Each polymer has its own melting point and properties, and mixing them produces a weak material."}',
  120,
  true
)
