INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-92',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"The Design of Hospital Corridors","passageText":"A hospital corridor carries patients, staff, beds and equipment, often at the same time. Its width is set by the need to pass without collision, but its design also affects recovery. Noise travels along hard surfaces, and poor lighting makes signs hard to read. Clear sightlines help visitors find their way, while handrails and seats give people somewhere to pause. Infection control adds requirements: surfaces must be cleanable, and there should be space for hand hygiene without blocking the route. A corridor is therefore a clinical space, not just a passage. When planners treat it as leftover area, they create bottlenecks that staff must work around every day.","gapSentence":{"before":"A hospital corridor carries patients, staff, beds and equipment, often at the same time. Its width is set by the need to pass without collision, but its design also affects recovery. Noise travels along hard surfaces, and poor lighting makes signs hard to read. Clear ","after":" help visitors find their way, while handrails and seats give people somewhere to pause. Infection control adds requirements: surfaces must be cleanable, and there should be space for hand hygiene without blocking the route. A corridor is therefore a clinical space, not just a passage. When planners treat it as leftover area, they create bottlenecks that staff must work around every day.","correct":"sightlines","options":["windows","colours","doors","sightlines"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The History of Medicine","How to Clean a Kitchen","Why Hospitals Are Expensive","The Design of Hospital Corridors"],"correctIndex":3},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["A hospital corridor is only a passage and has no clinical function.","Wider corridors always reduce the need for hand hygiene.","Noise and lighting have no effect on patients or staff.","Hospital corridors are clinical spaces where width, noise, wayfinding and infection control all matter."],"correctIndex":3},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["The effect is selective: emotionally charged material and skills practised the previous day benefit most.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Its width is set by the need to pass without collision, but its design also affects recovery.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms."]}',
  '{"gapCorrect":"sightlines","titleCorrectIndex":3,"mainIdeaCorrectIndex":3,"sentenceCorrectIndex":2,"highlightCorrectSubstring":"Its width is set by the need to pass without collision, but its design also affects recovery."}',
  120,
  true
)
