INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-93',
  'INTERACTIVE_READING',
  'C1',
  '{"passageTitle":"The Physics of a Bicycle Pump","passageText":"A bicycle pump seems simple, but its design determines how much effort a rider needs. A narrow barrel produces high pressure with a long stroke, while a wide barrel moves more air at lower pressure. The valve must open easily and close tightly, or the air escapes back into the pump. A flexible hose reduces the strain on the valve, and a gauge turns guesswork into a measurement. Heat is a useful signal: the barrel warms as the air is compressed, which is why a metal pump feels hot after a tyre is filled. Maintenance is mostly about the seals. A worn O-ring wastes effort long before the pump stops working completely.","gapSentence":{"before":"A bicycle pump seems simple, but its design determines how much effort a rider needs. A narrow barrel produces high pressure with a long stroke, while a wide barrel moves more air at lower pressure. The valve must open easily and close tightly, or the air escapes back into the pump. A flexible hose reduces the strain on the valve, and a ","after":" turns guesswork into a measurement. Heat is a useful signal: the barrel warms as the air is compressed, which is why a metal pump feels hot after a tyre is filled. Maintenance is mostly about the seals. A worn O-ring wastes effort long before the pump stops working completely.","correct":"gauge","options":["chain","brake","gauge","pedal"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How to Repair a Puncture","The Chemistry of Rubber","The Physics of a Bicycle Pump","The History of Cycling"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Pump effort depends on barrel geometry and seal condition, while a gauge replaces guesswork with measurement.","A wider barrel always produces higher pressure.","The valve has no effect on pumping efficiency.","A worn seal improves the pump by letting air escape."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A worn O-ring wastes effort long before the pump stops working completely.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve."]}',
  '{"gapCorrect":"gauge","titleCorrectIndex":2,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"A worn O-ring wastes effort long before the pump stops working completely."}',
  120,
  true
)
