INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-95',
  'INTERACTIVE_READING',
  'B2',
  '{"passageTitle":"The History of the Postage Stamp","passageText":"Before the postage stamp, sending a letter was often paid by the recipient, and the price depended on distance and on how many sheets were enclosed. The stamp changed the system by moving payment to the sender and making the price uniform. A small adhesive label could show that the fee had been paid, and the postmark proved when and where it entered the network. The innovation required more than paper: it needed reliable accounting, inspection and a public willing to prepay. Collectors later turned the stamp into an object of study, but its first purpose was administrative. Standardisation lowered the cost of communication and made the postal service a daily habit.","gapSentence":{"before":"Before the postage stamp, sending a letter was often paid by the ","after":", and the price depended on distance and on how many sheets were enclosed. The stamp changed the system by moving payment to the sender and making the price uniform. A small adhesive label could show that the fee had been paid, and the postmark proved when and where it entered the network. The innovation required more than paper: it needed reliable accounting, inspection and a public willing to prepay. Collectors later turned the stamp into an object of study, but its first purpose was administrative. Standardisation lowered the cost of communication and made the postal service a daily habit.","correct":"recipient","options":["carrier","printer","recipient","sender"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["The Rise of Email","The History of the Postage Stamp","How Trains Changed Travel","The Design of Paper Money"],"correctIndex":1},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["The postage stamp standardised prepaid postal charges and required new administrative systems.","Stamps made the recipient pay a price that varied by distance.","The postmark was used only for decoration.","Collectors invented the stamp before postal services existed."],"correctIndex":0},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["Standardisation lowered the cost of communication and made the postal service a daily habit.","A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","The effect is selective: emotionally charged material and skills practised the previous day benefit most.","The pattern repeated: private credit came first, public currency followed, and inflation punished the issuers who ignored the difference between a promise and a reserve."]}',
  '{"gapCorrect":"recipient","titleCorrectIndex":1,"mainIdeaCorrectIndex":0,"sentenceCorrectIndex":0,"highlightCorrectSubstring":"Standardisation lowered the cost of communication and made the postal service a daily habit."}',
  120,
  true
)
