INSERT INTO questions (id, type, difficulty_band, content_payload, correct_answers, time_limit_sec, is_active)
VALUES (
  'ibir-97',
  'INTERACTIVE_READING',
  'B1',
  '{"passageTitle":"How Seabirds Navigate by Smell","passageText":"Seabirds can find their colony across open water, and some appear to use smell as well as sight. The ocean releases gases from plankton and from the sea floor, and winds carry them in patterns that a bird can learn. Experiments with birds whose sense of smell was temporarily blocked found that they took longer to return. The evidence is not simple: smell works alongside magnetic cues, landmarks and memory. A change in wind can erase the signal or carry it from the wrong direction. Researchers therefore combine tracking with chemical measurements rather than relying on a single sense. Navigation is a set of fallbacks, and smell is one of them.","gapSentence":{"before":"Seabirds can find their colony across open water, and some appear to use smell as well as sight. The ocean releases ","after":" from plankton and from the sea floor, and winds carry them in patterns that a bird can learn. Experiments with birds whose sense of smell was temporarily blocked found that they took longer to return. The evidence is not simple: smell works alongside magnetic cues, landmarks and memory. A change in wind can erase the signal or carry it from the wrong direction. Researchers therefore combine tracking with chemical measurements rather than relying on a single sense. Navigation is a set of fallbacks, and smell is one of them.","correct":"gases","options":["salts","waves","currents","gases"]},"titleQuestion":{"question":"Choose the most appropriate academic title for this passage:","options":["How Fish Breathe Underwater","The Physics of Wind","How Seabirds Navigate by Smell","The History of Sailing"],"correctIndex":2},"mainIdeaQuestion":{"question":"What is the primary idea of the passage?","options":["Wind always helps a bird find its colony.","Blocking a bird sense of smell makes no difference to navigation.","Some seabirds use odour cues alongside other senses, and navigation relies on several fallbacks rather than one signal.","Seabirds navigate using sight alone."],"correctIndex":2},"highlightPrompt":"Highlight the sentence that carries the key claim described in the question.","sentenceOptions":["A mature canopy intercepts rainfall before it reaches the pavement, which reduces the volume of water that storm drains must carry during heavy storms.","During deep sleep, the hippocampus replays sequences of the day in compressed bursts, while the cortex gradually incorporates those patterns into longer-term storage.","Because the receipts were lighter than the coins, they circulated as payment, and the warehouses gradually became banks.","Navigation is a set of fallbacks, and smell is one of them."]}',
  '{"gapCorrect":"gases","titleCorrectIndex":2,"mainIdeaCorrectIndex":2,"sentenceCorrectIndex":3,"highlightCorrectSubstring":"Navigation is a set of fallbacks, and smell is one of them."}',
  120,
  true
)
